//! Accessibility boundary for an OSL-claimed native Discord window.
//!
//! This module never uses a WebView, DevTools, DOM/JavaScript injection,
//! credentials, cookies, private APIs, process memory, or message-history
//! scraping. A snapshot is requested on demand, bounded by node/time/result
//! limits, and contains only hashes and geometry. A separately calibrated
//! composer path may enter one non-secret OSL carrier after an explicit
//! trusted-overlay gesture. That carrier is the prepared message's wordbank
//! flagtext -- the prose-token cover for its cipher-store pointer, which is
//! already destined for a public Discord row. It is Discord-specific and reads
//! only bounded visible accessibility names, runtime ids, focus, bounds, and at
//! most the current composer value to prove it is empty or equals OSL's bounded
//! carrier. Prepared private text is reduced immediately to de-identified line
//! counts; only those counts and that public flagtext can reach the carrier
//! geometry planner -- the draft itself never does.
//! That value is never retained, returned, or logged. The visible labels are
//! user-confirmed context evidence, not provider-authenticated Discord account
//! proof. The adapter revalidates the signed window generation,
//! visible label, runtime id, bounds, and foreground focus before placement,
//! every compatibility character, and Enter.

use sha2::{Digest, Sha256};

use serde::{Deserialize, Serialize};

use std::sync::{
    atomic::{AtomicBool, Ordering},
    Mutex,
};
use std::time::{Duration, Instant};
use zeroize::Zeroizing;

use crate::discord_carrier_geometry::{
    self, CarrierGeometryInput, CarrierPlan, FixedPaddingSize, LineMetrics, PrivacyPaddingMode,
    VisibleStructure,
};

/// `Scan -> Preview -> Confirm -> Execute -> Verify -> Receipt` for deleting the
/// operator's OWN messages from Discord through Discord's own UI.
///
/// A child module rather than a sibling of this one on purpose: it is part of
/// this accessibility boundary, it uses this module's `stable_hash`, and its
/// tests belong to the same `native_discord_adapter` suite. It is NOT part of
/// Burn -- see `docs/design/burn-contract.md:14`, which stays true.
pub mod guided_deletion;

#[cfg(any(target_os = "windows", test, feature = "discord-qa-shell"))]
const MAX_CARRIERS: usize = 32;

/// Reported when OSL's own protected surface covers the Discord composer, so
/// the measurement cannot see the pixels it needs. The overlay guard responds
/// by hiding that surface and re-measuring instead of failing permanently.
pub(crate) const OVERLAY_OCCLUDES_COMPOSER: &str =
    "The OSL protected composer is covering the Discord composer";
#[cfg(any(target_os = "windows", test))]
const MAX_ACCESSIBLE_TEXT_BYTES: usize = 16 * 1024;
#[cfg(any(target_os = "windows", test))]
const DPC0_PREFIX: &str = "DPC0::";
#[cfg(any(target_os = "windows", test))]
const DISCORD_ENTER_SCAN_CODE: u16 = 0x1C;
/// Physical left-Shift scan code. Discord's composer treats Shift+Enter as a
/// soft line break and a bare Enter as "send now", so every newline inside a
/// multi-line carrier must be injected with Shift held down. A bare Enter in
/// the middle of the carrier would send a truncated first line and split the
/// protected message across several Discord rows.
#[cfg(any(target_os = "windows", test))]
const DISCORD_SHIFT_SCAN_CODE: u16 = 0x2A;

/// Physical scan codes for the only other keystrokes OSL ever injects: the ones
/// that take back text OSL typed itself.
///
/// Discord's composer is a Slate contenteditable, so text OSL typed as real
/// input has to be removed as real input too -- `ValuePattern.SetValue` would
/// leave Slate's own document holding the carrier. Left Control plus `A` selects
/// the whole composer, and the delete key that follows removes exactly that
/// selection. These are never used to touch anything OSL did not type: the
/// reclaim is gated on `may_reclaim_typed_carrier`.
#[cfg(any(target_os = "windows", test))]
const DISCORD_CONTROL_SCAN_CODE: u16 = 0x1D;
#[cfg(any(target_os = "windows", test))]
const DISCORD_A_SCAN_CODE: u16 = 0x1E;
/// The grey `Delete` key. Extended, so it must be injected with
/// `KEYEVENTF_EXTENDEDKEY`; the reclaim's second round falls back to Backspace,
/// which is not extended and deletes the same selection.
#[cfg(any(target_os = "windows", test))]
const DISCORD_DELETE_SCAN_CODE: u16 = 0x53;
#[cfg(any(target_os = "windows", test))]
const DISCORD_BACKSPACE_SCAN_CODE: u16 = 0x0E;

/// Escape, used only to close a Discord autocomplete overlay before the one Enter
/// that sends the carrier. Never sent while anything else is in flight, and every
/// use is followed by re-proving the exact composer text.
#[cfg(any(target_os = "windows", test))]
const DISCORD_ESCAPE_SCAN_CODE: u16 = 0x01;

const MAX_COVER_BYTES: usize = discord_carrier_geometry::DISCORD_CHARACTER_CAP * 4;

#[cfg(any(test, feature = "discord-qa-shell", target_os = "windows"))]
fn remapped_carrier_probe(
    row: AccessibilityBounds,
    sampled_host: [i32; 4],
    current_host: [i32; 4],
) -> Option<[i32; 2]> {
    let sampled_width = sampled_host[2].checked_sub(sampled_host[0])?;
    let sampled_height = sampled_host[3].checked_sub(sampled_host[1])?;
    let current_width = current_host[2].checked_sub(current_host[0])?;
    let current_height = current_host[3].checked_sub(current_host[1])?;
    let row_center_x = row.left.checked_add(row.right.checked_sub(row.left)? / 2)?;
    let row_center_y = row.top.checked_add(row.bottom.checked_sub(row.top)? / 2)?;
    if sampled_width <= 0
        || sampled_height <= 0
        || current_width <= 0
        || current_height <= 0
        || row_center_x < sampled_host[0]
        || row_center_x > sampled_host[2]
        || row_center_y < sampled_host[1]
        || row_center_y > sampled_host[3]
    {
        return None;
    }
    Some([
        current_host[0].checked_add(
            i32::try_from(
                i64::from(row_center_x - sampled_host[0]) * i64::from(current_width)
                    / i64::from(sampled_width),
            )
            .ok()?,
        )?,
        current_host[1].checked_add(
            i32::try_from(
                i64::from(row_center_y - sampled_host[1]) * i64::from(current_height)
                    / i64::from(sampled_height),
            )
            .ok()?,
        )?,
    ])
}

#[derive(Debug, Clone, Copy, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum DiscordCarrierMode {
    Atomic,
    Compatibility,
}

#[derive(Debug, Clone, Copy, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum DiscordCarrierStatus {
    Sent,
    CalibrationRequired,
    ContextChanged,
    ComposerUnavailable,
    ComposerNotEmpty,
    PlacementRejected,
    EnterRejected,
    /// The carrier was typed into the calibrated composer, and no read of that
    /// composer could prove it holds exactly the carrier, so Enter was withheld.
    ///
    /// Distinct from `ContextChanged`, which this used to be reported as, and the
    /// distinction is the whole reason the variant exists. `ContextChanged` says
    /// the composer or the overlay context stopped being the one OSL bound --
    /// which sends every reader at the window, focus and calibration subsystems.
    /// This failure is reported with the overlay context provably unchanged and
    /// the calibrated element provably still current: nothing moved, and the
    /// defect is in reading the composer back or in the keystrokes landing. The
    /// mismatch measurement written alongside it says which.
    CarrierUnconfirmed,
    PlatformUnsupported,
}

#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub enum DiscordProtectedSendOutcome {
    Sent,
    NotSent,
    DeliveryUncertain,
}

impl DiscordCarrierStatus {
    pub fn protected_send_outcome(
        self,
        placed: bool,
        enter_sent: bool,
    ) -> DiscordProtectedSendOutcome {
        if self == DiscordCarrierStatus::Sent && placed && enter_sent {
            DiscordProtectedSendOutcome::Sent
        } else if enter_sent {
            DiscordProtectedSendOutcome::DeliveryUncertain
        } else {
            DiscordProtectedSendOutcome::NotSent
        }
    }
}

#[derive(Debug, Clone, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DiscordComposerCalibrationReceipt {
    pub calibrated: bool,
    pub generation: u64,
    pub conversation_binding_hash: String,
}

#[derive(Debug, Clone, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DiscordCarrierReceipt {
    pub placed: bool,
    pub enter_sent: bool,
    pub status: DiscordCarrierStatus,
    pub mode: DiscordCarrierMode,
    pub compatibility_delay_ms: u16,
}

/// Product-context authority for one native carrier placement.
///
/// The source binding commits to the service, account, conversation and
/// recipient set that the broker approved. Only the hash is retained here, and
/// this type deliberately has no `Debug`/`Display`, so those identifiers cannot
/// be formatted by accident.
#[derive(Clone, Eq, PartialEq)]
pub struct NativeDiscordPlacementContext {
    service_account_conversation_recipients_binding_hash: String,
    mode: DiscordCarrierMode,
}

impl NativeDiscordPlacementContext {
    pub fn new(scope_binding: &str, mode: DiscordCarrierMode) -> Self {
        Self {
            service_account_conversation_recipients_binding_hash: stable_hash(
                "discord-native-placement-context",
                scope_binding,
            ),
            mode,
        }
    }

    fn authorizes(&self, scope_binding: &str, mode: DiscordCarrierMode) -> bool {
        !scope_binding.is_empty()
            && self.mode == mode
            && self.service_account_conversation_recipients_binding_hash
                == stable_hash("discord-native-placement-context", scope_binding)
    }
}

#[cfg(any(target_os = "windows", test))]
#[derive(Clone, PartialEq, Eq)]
struct ComposerDiscoveryProfile {
    composer_role: String,
    composer_name_prefixes: Vec<String>,
}

#[cfg(any(target_os = "windows", test))]
impl Default for ComposerDiscoveryProfile {
    fn default() -> Self {
        Self {
            composer_role: "text".to_owned(),
            composer_name_prefixes: vec!["Message ".to_owned()],
        }
    }
}

#[cfg(any(target_os = "windows", test))]
impl ComposerDiscoveryProfile {
    fn from_verified_profile(
        profile: &adapter_profile::ProfilePayload,
        now_unix_seconds: u64,
    ) -> Result<Self, &'static str> {
        profile
            .validate_for_use(now_unix_seconds)
            .map_err(|_| "profile-not-usable")?;
        if profile.app.stable_id != "discord" {
            return Err("profile-not-discord");
        }

        let mut composer_role = None::<String>;
        let mut composer_name_prefixes = Vec::<String>::new();
        for selector in profile.selectors.iter().filter(|selector| {
            selector.required && selector.kind == adapter_profile::SelectorKind::ComposerInput
        }) {
            match &selector.strategy {
                adapter_profile::SelectorStrategy::Accessibility { role, .. } => {
                    if valid_profile_anchor(role) {
                        composer_role = Some(role.clone());
                    }
                }
                adapter_profile::SelectorStrategy::TextAnchor { starts_with } => {
                    if valid_profile_anchor(starts_with) {
                        composer_name_prefixes.push(starts_with.clone());
                    }
                }
                adapter_profile::SelectorStrategy::Css { .. } => {}
            }
        }

        let composer_role = composer_role.ok_or("profile-missing-composer-role")?;
        if composer_name_prefixes.is_empty() {
            return Err("profile-missing-composer-anchor");
        }
        Ok(Self {
            composer_role,
            composer_name_prefixes,
        })
    }

    fn accepts_msaa_role(&self, role: u32) -> bool {
        role == MSAA_ROLE_SYSTEM_TEXT
            && matches!(self.composer_role.as_str(), "text" | "editable_text")
    }

    fn conversation_from_composer_name<'a>(&self, name: &'a str) -> Option<&'a str> {
        let value = name.trim();
        self.composer_name_prefixes.iter().find_map(|prefix| {
            let rest = value
                .strip_prefix(prefix)
                .or_else(|| value.strip_prefix(&prefix.to_ascii_lowercase()))?
                .trim_start_matches(['@', '#'])
                .trim();
            bounded_identity(Some(rest))
        })
    }
}

#[cfg(any(target_os = "windows", test))]
fn valid_profile_anchor(value: &str) -> bool {
    !value.trim().is_empty()
        && value.trim() == value
        && value.len() <= 128
        && !value.chars().any(char::is_control)
}

/// Content-free typography and line-box proof for the exact native composer.
/// Bounds are screen-space pixels inside the verified editable role-42 node.
/// Optional font fields are published only when one converted TextPattern
/// supplies every bounded attribute.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct VerifiedComposerTextPresentation {
    pub bounds: AccessibilityBounds,
    pub font_family: Option<String>,
    pub font_size_milli_points: Option<u32>,
    pub font_weight: Option<u16>,
    pub line_height_milli_px: Option<u32>,
}

/// Metrics-only input from a trusted local renderer. It cannot contain draft,
/// carrier, ciphertext, account, or conversation text.
#[derive(Debug, Clone, Copy, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase")]
pub struct DiscordCarrierLayout {
    pub content_width_px: f64,
    pub average_grapheme_width_px: f64,
    pub line_height_px: f64,
    pub zoom: f64,
    pub density: f64,
    pub padding: DiscordCarrierPadding,
    /// Explicit surrounding Discord row kind from the trusted local renderer.
    pub row_kind: DiscordCarrierRowKind,
}

#[derive(Debug, Clone, Copy, Deserialize, Eq, PartialEq)]
#[serde(rename_all = "camelCase")]
pub enum DiscordCarrierPadding {
    ShapeMatched,
    FixedCompact,
    FixedStandard,
    FixedTall,
}

#[derive(Debug, Clone, Copy, Deserialize, Eq, PartialEq)]
#[serde(rename_all = "camelCase")]
pub enum DiscordCarrierRowKind {
    PlainText,
    Markdown,
    Media,
    Reply,
}

impl DiscordCarrierPadding {
    fn geometry_mode(self) -> PrivacyPaddingMode {
        match self {
            Self::ShapeMatched => PrivacyPaddingMode::ShapeMatched,
            Self::FixedCompact => PrivacyPaddingMode::FixedSize(FixedPaddingSize::Compact),
            Self::FixedStandard => PrivacyPaddingMode::FixedSize(FixedPaddingSize::Standard),
            Self::FixedTall => PrivacyPaddingMode::FixedSize(FixedPaddingSize::Tall),
        }
    }
}

