    #[test]
    fn qa_post_mutation_equivalence_accepts_only_runtime_id_remount() {
        let expected = test_composer_binding(vec![1, 2, 3]);
        let remounted = test_composer_binding(vec![9, 8, 7]);
        assert!(qa_post_mutation_binding_equivalent(&expected, &remounted));

        let mut semantic_changes = Vec::new();
        let mut changed = remounted.clone();
        changed.generation += 1;
        semantic_changes.push(changed);
        let mut changed = remounted.clone();
        changed.scope_binding_hash = "other".to_owned();
        semantic_changes.push(changed);
        let mut changed = remounted.clone();
        changed.conversation_binding_hash = "other".to_owned();
        semantic_changes.push(changed);
        let mut changed = remounted.clone();
        changed.composer_name_hash = "other".to_owned();
        semantic_changes.push(changed);
        let mut changed = remounted.clone();
        changed.automation_id_hash = "other".to_owned();
        semantic_changes.push(changed);
        let mut changed = remounted.clone();
        changed.class_name_hash = "other".to_owned();
        semantic_changes.push(changed);
        assert!(semantic_changes
            .iter()
            .all(|actual| !qa_post_mutation_binding_equivalent(&expected, actual)));

        let mut changed_edit_bounds = remounted.clone();
        changed_edit_bounds.bounds.right += 1;
        assert!(!qa_post_mutation_binding_equivalent(
            &expected,
            &changed_edit_bounds
        ));

        let mut changed_display_bounds = remounted.clone();
        changed_display_bounds.display_bounds.bottom += 1;
        assert!(!qa_post_mutation_binding_equivalent(
            &expected,
            &changed_display_bounds
        ));

        #[cfg(all(target_os = "windows", feature = "discord-qa-shell"))]
        assert!(windows::carrier_post_mutation_binding_matches(
            &expected, &remounted
        ));
        #[cfg(all(target_os = "windows", not(feature = "discord-qa-shell")))]
        assert!(!windows::carrier_post_mutation_binding_matches(
            &expected, &remounted
        ));
    }

