    #[test]
    fn msaa_bridge_labels_name_the_exact_cross_check_that_refused() {
        assert_eq!(
            msaa_bridge_outcome(false, true, true, true, true),
            MsaaBridgeOutcome::BoundsMismatch
        );
        assert_eq!(
            msaa_bridge_outcome(true, false, true, true, true),
            MsaaBridgeOutcome::NameMismatch
        );
        assert_eq!(
            msaa_bridge_outcome(true, true, false, true, true),
            MsaaBridgeOutcome::TypeRejected
        );
        assert_eq!(
            msaa_bridge_outcome(true, true, true, false, false),
            MsaaBridgeOutcome::ValueUnusable
        );
        assert_eq!(
            msaa_bridge_outcome(true, true, true, true, false),
            MsaaBridgeOutcome::ValueUnusable
        );
        assert_eq!(
            msaa_bridge_outcome(true, true, true, true, true),
            MsaaBridgeOutcome::Accepted
        );
        // A whole-window bridged rectangle must read as a mismatch, not as a
        // success: binding the protected overlay to it would be a worse bug than
        // failing to calibrate.
        assert_eq!(
            msaa_bridge_stage(msaa_bridge_outcome(false, true, true, true, true)),
            "msaa_bridge_bounds_mismatch"
        );
        assert_eq!(
            msaa_bridge_stage(MsaaBridgeOutcome::CallFailed),
            "msaa_bridge_call_failed"
        );
        assert_eq!(
            msaa_bridge_stage(MsaaBridgeOutcome::NameMismatch),
            "msaa_bridge_name_mismatch"
        );
        assert_eq!(
            msaa_bridge_stage(MsaaBridgeOutcome::TypeRejected),
            "msaa_bridge_type_rejected"
        );
        assert_eq!(
            msaa_bridge_stage(MsaaBridgeOutcome::ValueUnusable),
            "msaa_bridge_value_unusable"
        );
        assert_eq!(
            msaa_bridge_stage(MsaaBridgeOutcome::Accepted),
            "msaa_bridge_accepted"
        );
    }

    /// `msaa_bridge_call_failed` fuses two events and each fans out further.
    ///
    /// On 2026-07-26 the bridge went from 96 consecutive `msaa_bridge_accepted`
    /// to failing on every locate, and the trail could say only "it failed" --
    /// so "this thread's COM apartment is wrong", "Discord's provider is gone"
    /// and "the composer element is off screen after a restore" were one
    /// indistinguishable label with three different fixes.
    #[test]
    fn every_bridge_failure_names_which_check_spoke_and_they_are_all_distinct() {
        use MsaaBridgeCallClass as Class;
        use MsaaBridgeRefusal as Refusal;

        let refusals = [
            Refusal::Call(Class::Apartment),
            Refusal::Call(Class::ProviderGone),
            Refusal::Call(Class::Busy),
            Refusal::Call(Class::Refused),
            Refusal::Call(Class::AccessDenied),
            Refusal::Call(Class::Resources),
            Refusal::Call(Class::Unclassified),
            Refusal::ProcessUnreadable,
            Refusal::ProcessUntrusted,
            Refusal::Offscreen,
            Refusal::Disabled,
            Refusal::BoundsUnreadable,
            Refusal::OutsideRoot,
        ];
        let labels: Vec<&str> = refusals
            .iter()
            .copied()
            .map(msaa_bridge_refusal_stage)
            .collect();

        // Distinct, or two different causes read as one -- which is the defect.
        let mut unique = labels.clone();
        unique.sort_unstable();
        unique.dedup();
        assert_eq!(unique.len(), labels.len());

        // Fixed, self-describing, and free of anything a draft or conversation
        // could be recovered from.
        for label in &labels {
            assert!(label.starts_with("msaa_bridge_failed_"));
            assert!(label.is_ascii());
            assert!(!label.contains(' '));
            assert!(!label.contains('{'));
        }
        // Distinguishable from the outcome label they sit beside, so a grep for
        // one never matches the other.
        assert!(!labels.contains(&msaa_bridge_stage(MsaaBridgeOutcome::CallFailed)));
    }

    #[test]
    fn the_bridge_hresult_table_separates_apartment_from_a_dead_provider() {
        use MsaaBridgeCallClass as Class;

        // OSL's own threading, and permanent until the call site is fixed.
        for (code, name) in [
            (0x8004_01F0u32, "CO_E_NOTINITIALIZED"),
            (0x8001_0106, "RPC_E_CHANGED_MODE"),
            (0x8001_010E, "RPC_E_WRONG_THREAD"),
            (0x8001_010F, "RPC_E_THREAD_NOT_INIT"),
        ] {
            assert_eq!(
                msaa_bridge_call_class(code as i32),
                Class::Apartment,
                "{name} is an apartment failure"
            );
        }
        // Discord's provider or the RPC channel is gone. Permanent for THIS
        // element; a fresh discovery can still succeed.
        for (code, name) in [
            (0x8001_0108u32, "RPC_E_DISCONNECTED"),
            (0x8001_0105, "RPC_E_SERVERFAULT"),
            (0x8007_06BA, "RPC_S_SERVER_UNAVAILABLE"),
            (0x8007_06BE, "RPC_S_CALL_FAILED"),
            (0x8004_0201, "UIA_E_ELEMENTNOTAVAILABLE"),
        ] {
            assert_eq!(
                msaa_bridge_call_class(code as i32),
                Class::ProviderGone,
                "{name} means the provider is gone"
            );
        }
        // Alive and declining right now. The ONLY retryable class.
        for (code, name) in [
            (0x8001_0001u32, "RPC_E_CALL_REJECTED"),
            (0x8001_010A, "RPC_E_SERVERCALL_RETRYLATER"),
            (0x8001_011F, "RPC_E_TIMEOUT"),
            (0x8013_1505, "UIA_E_TIMEOUT"),
        ] {
            assert_eq!(
                msaa_bridge_call_class(code as i32),
                Class::Busy,
                "{name} is retryable"
            );
        }
        assert_eq!(
            msaa_bridge_call_class(0x8007_0057u32 as i32),
            Class::Refused
        );
        assert_eq!(
            msaa_bridge_call_class(0x8007_0005u32 as i32),
            Class::AccessDenied
        );
        assert_eq!(
            msaa_bridge_call_class(0x8007_000Eu32 as i32),
            Class::Resources
        );
        // An unknown code is named as unknown, never silently folded into a
        // class whose fix would then be the wrong one.
        assert_eq!(
            msaa_bridge_call_class(0x8000_BEEFu32 as i32),
            Class::Unclassified
        );

        // Exactly one class may be retried, and it is the one where the provider
        // answered. Everything else is a statement about the element, the
        // process or OSL's threading, and asking again gets the same answer.
        assert!(msaa_bridge_refusal_is_retryable(MsaaBridgeRefusal::Call(
            Class::Busy
        )));
        for refusal in [
            MsaaBridgeRefusal::Call(Class::Apartment),
            MsaaBridgeRefusal::Call(Class::ProviderGone),
            MsaaBridgeRefusal::Call(Class::Refused),
            MsaaBridgeRefusal::Call(Class::AccessDenied),
            MsaaBridgeRefusal::Call(Class::Resources),
            MsaaBridgeRefusal::Call(Class::Unclassified),
            MsaaBridgeRefusal::ProcessUnreadable,
            MsaaBridgeRefusal::ProcessUntrusted,
            MsaaBridgeRefusal::Offscreen,
            MsaaBridgeRefusal::Disabled,
            MsaaBridgeRefusal::BoundsUnreadable,
            MsaaBridgeRefusal::OutsideRoot,
        ] {
            assert!(!msaa_bridge_refusal_is_retryable(refusal));
        }
    }

    /// The classification must never have cost a check its strictness.
    #[test]
    fn naming_the_bridge_refusal_relaxed_no_trust_rule() {
        let source = adapter_source();
        // `trusted_visible_element` is now a `.ok()` wrapper, so every one of its
        // existing callers keeps the identical behaviour it had.
        assert!(source.contains(
            "trusted_visible_element_classified(element, root_bounds, process_is_trusted).ok()"
        ));
        let classified = nested_function_body(source, "fn trusted_visible_element_classified(");
        // All five checks survive, in the order they were always stated.
        for check in [
            "CurrentProcessId",
            "process_is_trusted(process_id as u32)",
            "CurrentIsOffscreen",
            "CurrentIsEnabled",
            "element_bounds(element)",
            "bounds.left >= root_bounds.left",
            "bounds.bottom <= root_bounds.bottom",
        ] {
            assert!(classified.contains(check), "{check} must still be asked");
        }
        // And the bridge still returns an element ONLY when the classified check
        // said `Ok` -- naming a refusal must not become a way past it.
        let bridge = nested_function_body(source, "fn bridge_msaa_element(");
        assert!(bridge.contains("Ok(_) => MsaaBridgeElement::Bridged(element),"));
        assert!(bridge.contains("Err(refusal) => MsaaBridgeElement::Untrusted(refusal),"));
    }

    #[test]
    fn msaa_route_labels_separate_budget_starvation_from_an_absent_node() {
        assert_eq!(
            msaa_route_outcome(true, true, false, 3, 3),
            MsaaRouteOutcome::Bound
        );
        assert_eq!(msaa_route_stage(MsaaRouteOutcome::Bound), None);
        // Discovery worked and the bridge refused: the bridge label already said
        // why, so the route must not overwrite it with a budget story.
        assert_eq!(
            msaa_route_outcome(false, true, true, 3, 3),
            MsaaRouteOutcome::BridgeRejected
        );
        assert_eq!(msaa_route_stage(MsaaRouteOutcome::BridgeRejected), None);
        // A route that ran and spent its OWN slice. This is not the same fact as
        // "OSL was starved before it started", and it must not borrow that label:
        // `msaa_route_skipped_no_budget` says something was skipped, and this route
        // was not skipped -- it walked 240 nodes' worth of `accLocation` calls and
        // ran itself out.
        assert_eq!(
            msaa_route_outcome(false, false, true, 3, 3),
            MsaaRouteOutcome::OwnBudgetExhausted
        );
        assert_eq!(
            msaa_route_stage(MsaaRouteOutcome::OwnBudgetExhausted),
            Some("msaa_route_exhausted_own_budget")
        );
        // The entry skip keeps the original wording, which is now true of it.
        assert_eq!(
            msaa_route_stage(MsaaRouteOutcome::NoBudgetOnEntry),
            Some("msaa_route_skipped_no_budget")
        );
        assert_eq!(
            msaa_route_outcome(false, false, false, 3, 3),
            MsaaRouteOutcome::NoEditableNode
        );
        assert_eq!(
            msaa_route_stage(MsaaRouteOutcome::NoEditableNode),
            Some("msaa_no_editable_node")
        );
    }

    /// The mislabelling that sent a live diagnosis down the wrong causal path: a
    /// route that starved itself reported "no budget" AND erased
    /// `msaa_no_editable_node`, so the trail could say neither what stopped the
    /// route nor what the route had already seen.
    #[test]
    fn a_self_starved_msaa_route_still_reports_what_it_saw() {
        // Why it stopped, and what it saw, are two labels now -- from two
        // vocabularies that cannot be confused for one another.
        assert_eq!(
            msaa_route_stage(MsaaRouteOutcome::OwnBudgetExhausted),
            Some("msaa_route_exhausted_own_budget")
        );
        assert_eq!(
            msaa_walk_reading_stage(0, 0),
            "msaa_walk_saw_no_owned_points"
        );
        assert_eq!(
            msaa_walk_reading_stage(4, 0),
            "msaa_walk_saw_no_accessible_nodes"
        );
        assert_eq!(
            msaa_walk_reading_stage(4, 4),
            "msaa_walk_saw_no_editable_node"
        );
        // The "what it saw" labels are distinct from every verdict label, so a
        // partial measurement can never read as a completed one.
        let verdicts = [
            MsaaRouteOutcome::NoBudgetOnEntry,
            MsaaRouteOutcome::OwnBudgetExhausted,
            MsaaRouteOutcome::NoEditableNode,
            MsaaRouteOutcome::NoPointsOwned,
            MsaaRouteOutcome::NoAccessibleAtPoints,
        ]
        .map(msaa_route_stage);
        for reading in [
            msaa_walk_reading_stage(0, 0),
            msaa_walk_reading_stage(4, 0),
            msaa_walk_reading_stage(4, 4),
        ] {
            assert!(!verdicts.contains(&Some(reading)));
        }
        // And they are distinct from each other.
        assert_ne!(msaa_walk_reading_stage(0, 0), msaa_walk_reading_stage(4, 0));
        assert_ne!(msaa_walk_reading_stage(4, 0), msaa_walk_reading_stage(4, 4));
    }

    #[test]
    fn msaa_route_never_blames_discord_for_a_probe_it_could_not_make() {
        // The live placement failure: every probe point was owned by OSL's own
        // surfaces, so the route issued no MSAA call at all. Reporting that as
        // `msaa_no_editable_node` claimed something about Discord's tree that had
        // never been measured, and made the trail unreadable.
        assert_eq!(
            msaa_route_outcome(false, false, false, 0, 0),
            MsaaRouteOutcome::NoPointsOwned
        );
        assert_eq!(
            msaa_route_stage(MsaaRouteOutcome::NoPointsOwned),
            Some("msaa_no_probe_points_owned")
        );
        // Discord owned the pixels and handed out no accessible object there,
        // which is a third, separate defect.
        assert_eq!(
            msaa_route_outcome(false, false, false, 4, 0),
            MsaaRouteOutcome::NoAccessibleAtPoints
        );
        assert_eq!(
            msaa_route_stage(MsaaRouteOutcome::NoAccessibleAtPoints),
            Some("msaa_no_accessible_at_points")
        );
        // Nodes were walked and none was a plausible composer: only now is
        // `msaa_no_editable_node` an honest statement about Discord.
        assert_eq!(
            msaa_route_outcome(false, false, false, 4, 4),
            MsaaRouteOutcome::NoEditableNode
        );
        // A tripped bound still outranks both new readings, and a bridge refusal
        // outranks everything below `Bound`.
        assert_eq!(
            msaa_route_outcome(false, false, true, 0, 0),
            MsaaRouteOutcome::OwnBudgetExhausted
        );
        assert_eq!(
            msaa_route_outcome(false, true, false, 0, 0),
            MsaaRouteOutcome::BridgeRejected
        );
        // Every route label is a distinct fixed string.
        let labels = [
            MsaaRouteOutcome::NoBudgetOnEntry,
            MsaaRouteOutcome::OwnBudgetExhausted,
            MsaaRouteOutcome::NoEditableNode,
            MsaaRouteOutcome::NoPointsOwned,
            MsaaRouteOutcome::NoAccessibleAtPoints,
        ]
        .map(msaa_route_stage);
        for (index, label) in labels.iter().enumerate() {
            assert!(label.is_some());
            assert!(!labels[..index].contains(label));
        }
    }

    #[test]
    fn probe_line_of_sight_labels_separate_proven_transparency_from_applied_transparency() {
        assert_eq!(
            probe_line_of_sight_stage(ProbeLineOfSight::Cleared),
            "locate_click_through_cleared_line_of_sight"
        );
        assert_eq!(
            probe_line_of_sight_stage(ProbeLineOfSight::ClearedAfterWidening),
            "locate_click_through_extended"
        );
        assert_eq!(
            probe_line_of_sight_stage(ProbeLineOfSight::Blocked),
            "locate_click_through_line_of_sight_blocked"
        );
        // Only the two cleared readings mean the probes can reach Discord.
        assert!(probe_line_of_sight_is_clear(ProbeLineOfSight::Cleared));
        assert!(probe_line_of_sight_is_clear(
            ProbeLineOfSight::ClearedAfterWidening
        ));
        assert!(!probe_line_of_sight_is_clear(ProbeLineOfSight::Blocked));
        // Distinct labels, otherwise the trail cannot tell the three apart.
        let labels = [
            ProbeLineOfSight::Cleared,
            ProbeLineOfSight::ClearedAfterWidening,
            ProbeLineOfSight::Blocked,
        ]
        .map(probe_line_of_sight_stage);
        for (index, label) in labels.iter().enumerate() {
            assert!(!labels[..index].contains(label));
        }
    }

    #[test]
    fn widening_the_click_through_set_stays_bounded_and_deduplicated() {
        let mut set = vec![10, 20];
        // Nothing new: the widening loop must be able to see that it has stopped
        // making progress, or it would spin against the same window forever.
        assert_eq!(merge_self_occluding_windows(&mut set, &[20, 10]), 0);
        assert_eq!(set, vec![10, 20]);
        assert_eq!(merge_self_occluding_windows(&mut set, &[30, 20, 40]), 2);
        assert_eq!(set, vec![10, 20, 30, 40]);
        // The bound a guard may ever cover is unchanged.
        assert_eq!(
            merge_self_occluding_windows(&mut set, &[50, 60, 70, 80]),
            MAX_PROBE_SELF_WINDOWS - 4
        );
        assert_eq!(set.len(), MAX_PROBE_SELF_WINDOWS);
        assert_eq!(merge_self_occluding_windows(&mut set, &[90]), 0);
        assert_eq!(set.len(), MAX_PROBE_SELF_WINDOWS);
    }

    #[test]
    fn probe_failure_labels_separate_unreachable_points_from_rejected_starts() {
        // Fully self-occluded and no focused element: the round issued no
        // `ElementFromPoint` at all, so it learnt nothing about Discord.
        assert_eq!(
            composer_probe_failure_stage(false, 0, 0),
            "locate_probe_no_points_owned"
        );
        // Discord owned the pixels and answered nothing this process may walk.
        assert_eq!(
            composer_probe_failure_stage(false, 5, 0),
            "locate_probe_points_yielded_no_element"
        );
        // Starts existed and every cross-check refused them. This is the only
        // reading that says something about Discord's own tree, and it must win
        // from either start source.
        assert_eq!(
            composer_probe_failure_stage(true, 0, 0),
            "locate_probe_starts_rejected"
        );
        assert_eq!(
            composer_probe_failure_stage(false, 5, 2),
            "locate_probe_starts_rejected"
        );
        assert_eq!(
            composer_probe_failure_stage(true, 5, 2),
            "locate_probe_starts_rejected"
        );
    }

