    #[test]
    fn msaa_route_gets_a_real_share_of_the_round_not_the_leftovers() {
        // A share of the existing round, never an addition to it: the guard
        // thread's refresh cadence must not get more expensive.
        assert!(MSAA_ROUTE_BUDGET_SHARE_PERCENT > 50);
        assert!(MSAA_ROUTE_BUDGET_SHARE_PERCENT < 100);
        let timeout = std::time::Duration::from_secs(2);
        let budget = msaa_route_budget(timeout);
        assert_eq!(budget, std::time::Duration::from_millis(1_200));
        assert!(budget < timeout);
        assert!(msaa_route_has_budget(std::time::Duration::ZERO, budget));
        assert!(msaa_route_has_budget(
            std::time::Duration::from_millis(1_100),
            budget
        ));
        // Nothing usable left: the route says so instead of burning the
        // fallback's slice.
        assert!(!msaa_route_has_budget(
            std::time::Duration::from_millis(1_101),
            budget
        ));
        assert!(!msaa_route_has_budget(
            std::time::Duration::from_millis(5_000),
            budget
        ));
        assert!(!msaa_route_has_budget(
            std::time::Duration::ZERO,
            std::time::Duration::from_millis(99)
        ));
    }

