    #[test]
    fn carrier_source_is_bounded_and_control_free() {
        assert!(valid_cover("Sounds good to me."));
        assert!(valid_cover("🔒 OSL private message"));
        // Wordbank flagtext is what the carrier now carries.
        assert!(valid_cover(TEST_FLAGTEXT));
        // A multi-line cover is what the planner now normally produces: the
        // flagtext's separators are shaped to the row count of the plaintext
        // painted over it, so `'\n'` must stay legal here.
        assert!(valid_cover("first row\nsecond row"));
        assert!(!valid_cover(""));
        assert!(!valid_cover("line one\rline two"));
        assert!(!valid_cover(
            &"x".repeat(discord_carrier_geometry::DISCORD_CHARACTER_CAP + 1)
        ));
        assert!(!valid_cover(&"🔒".repeat(
            discord_carrier_geometry::DISCORD_CHARACTER_CAP / 2 + 1
        )));
        assert!(!valid_cover(&"x".repeat(MAX_COVER_BYTES + 1)));
    }

    /// Stand-in for a real `stego::encode_token` prose cover: wordbank chat
    /// prose, no marker, no base64 and no hex, single-space separated as the
    /// encoder hands it over. The planner shapes its separators to the row count
    /// of the text painted over it, so a placed carrier is word-for-word this and
    /// not byte-for-byte.
    const TEST_FLAGTEXT: &str = "ok i will weekend again with you get what i was thinking usual";

    /// The words a placed carrier must still be, in order — the only property the
    /// pointer's recipient depends on.
    fn same_words(carrier: &str, flagtext: &str) -> bool {
        carrier.split_whitespace().eq(flagtext.split_whitespace())
            && carrier.chars().count() == flagtext.chars().count()
    }

    fn measured_layout() -> DiscordCarrierLayout {
        DiscordCarrierLayout {
            content_width_px: 240.0,
            average_grapheme_width_px: 8.0,
            line_height_px: 20.0,
            zoom: 1.0,
            density: 1.0,
            padding: DiscordCarrierPadding::ShapeMatched,
            row_kind: DiscordCarrierRowKind::PlainText,
        }
    }

    #[test]
    fn prepared_text_is_immediately_reduced_to_unicode_aware_counts() {
        let visual = deidentify_prepared_visual_structure("e\u{301} 👨‍👩‍👧‍👦\n\nx");
        assert_eq!(visual.hard_line_graphemes, [3, 0, 1]);
        assert!(!visual.has_markdown);

        let markdown = deidentify_prepared_visual_structure("**private**");
        assert!(markdown.has_markdown);
    }

    #[test]
    fn prepared_visual_shape_is_scope_bound_and_consumed_once() {
        let state = NativeDiscordComposerState::default();
        state.remember_prepared_visual_structure(
            "scope-a",
            deidentify_prepared_visual_structure(&"x".repeat(40)),
            TEST_FLAGTEXT.to_owned(),
        );
        let plan = state.take_prepared_carrier_plan("scope-a", Some(measured_layout()));
        assert_eq!(
            plan.decision,
            discord_carrier_geometry::CarrierDecision::RowOverlay
        );
        // The carrier is the prepared message's own flagtext, word for word, with
        // its separators shaped to the rows the plaintext paints over. A
        // 40-grapheme draft asks for two rows in this 30-character column and this
        // cover cannot fit in fewer than three, so the row is the payload's floor.
        let carrier = plan.cover_text().unwrap();
        assert!(same_words(&carrier, TEST_FLAGTEXT));
        assert_eq!(plan.target.unwrap().line_count, 3);
        assert_eq!(carrier.split('\n').count(), 3);

        let consumed = state.take_prepared_carrier_plan("scope-a", Some(measured_layout()));
        assert_eq!(
            consumed.decision,
            discord_carrier_geometry::CarrierDecision::ProtectedViewportFallback(
                discord_carrier_geometry::FallbackReason::UnknownStructure
            )
        );
    }

    #[test]
    fn the_carrier_is_this_messages_flagtext_and_never_a_constant() {
        let first_flagtext = "ok i will weekend again with you get what i was thinking usual";
        let second_flagtext = "on yeah i feel work think it the week and im friday same thing";
        let mut carriers = Vec::new();
        for (draft, flagtext) in [
            ("first private draft", first_flagtext),
            // A different draft AND a different pointer cover.
            (
                "a completely different and much longer private draft",
                second_flagtext,
            ),
            // Same draft text, different message, therefore a different pointer.
            ("first private draft", second_flagtext),
        ] {
            let state = NativeDiscordComposerState::default();
            state.remember_prepared_visual_structure(
                "scope",
                deidentify_prepared_visual_structure(draft),
                flagtext.to_owned(),
            );
            let plan = state.take_prepared_carrier_plan("scope", Some(measured_layout()));
            let carrier = plan.cover_text().expect("a prepared send places a row");
            assert!(
                same_words(&carrier, flagtext),
                "the carrier must be this message's flagtext, word for word"
            );
            // Shaping rewrites separators only, so a `'\n'` is the one difference
            // from the encoder's bytes and it must be typeable as one message.
            assert!(!carrier.contains("\n\n") && !carrier.contains('\r'));
            assert!(carrier_input_steps(&carrier)
                .iter()
                .all(|step| !matches!(step, CarrierInputStep::Text(""))));
            for retired in [
                "OSL protected message.",
                "Private message protected.",
                "Protected placeholder.",
                "OSL private placeholder.",
            ] {
                assert!(!carrier.contains(retired), "placeholder prose came back");
            }
            carriers.push(carrier);
        }
        assert_ne!(carriers[0], carriers[1]);
        assert_ne!(carriers[0], carriers[2]);
    }

    /// The wiring proof: a plan whose row was shaped to a multi-row plaintext
    /// types as exactly one Shift+Enter per row boundary and never a bare Enter,
    /// which would send a partial message.
    #[test]
    fn a_shaped_multi_row_plan_types_one_shift_enter_per_row_boundary() {
        let state = NativeDiscordComposerState::default();
        // Four hard lines paint four rows in the measured column.
        state.remember_prepared_visual_structure(
            "scope",
            deidentify_prepared_visual_structure("one\ntwo\nthree\nfour"),
            TEST_FLAGTEXT.to_owned(),
        );
        let plan = state.take_prepared_carrier_plan("scope", Some(measured_layout()));
        let carrier = plan.cover_text().expect("a four-row cover is placeable");
        let rows = plan.target.unwrap().line_count;
        assert_eq!(rows, 4);
        assert!(same_words(&carrier, TEST_FLAGTEXT));
        assert!(valid_cover(&carrier));

        let steps = carrier_input_steps(&carrier);
        let breaks = steps
            .iter()
            .filter(|step| matches!(step, CarrierInputStep::ShiftEnter))
            .count();
        assert_eq!(breaks, rows - 1, "one soft break per row boundary");
        // Every other step is real text: no empty run, so no step degenerates.
        assert_eq!(steps.len(), rows + breaks);
        assert!(steps
            .iter()
            .all(|step| !matches!(step, CarrierInputStep::Text(""))));
    }

    #[test]
    fn a_send_with_no_prepared_flagtext_never_places_a_row() {
        let state = NativeDiscordComposerState::default();
        state.remember_prepared_visual_structure(
            "scope",
            deidentify_prepared_visual_structure("private"),
            String::new(),
        );
        let plan = state.take_prepared_carrier_plan("scope", Some(measured_layout()));
        assert_eq!(
            plan.decision,
            discord_carrier_geometry::CarrierDecision::ProtectedViewportFallback(
                discord_carrier_geometry::FallbackReason::FlagtextUnavailable
            )
        );
        assert_eq!(plan.cover_text(), None);
        // Nothing to type means nothing is accepted for placement either.
        assert!(!valid_cover(""));
    }

    #[test]
    fn the_carrier_receipt_carries_only_fixed_labels_and_counts() {
        let draft = "the operator's private words";
        let flagtext = "ok i will weekend again with you get what i was thinking usual";
        let receipt = DiscordCarrierReceipt {
            placed: true,
            enter_sent: false,
            status: DiscordCarrierStatus::PlacementRejected,
            mode: DiscordCarrierMode::Atomic,
            compatibility_delay_ms: compatibility_delay_ms(6),
        };
        let encoded = serde_json::to_string(&receipt).expect("receipt serialises");
        // No draft, and not even the public carrier, is echoed into a receipt.
        assert!(!encoded.contains(draft));
        assert!(!encoded.contains("private"));
        assert!(!encoded.contains(flagtext));
        assert_eq!(
            encoded,
            "{\"placed\":true,\"enterSent\":false,\"status\":\"placementRejected\",\"mode\":\"atomic\",\"compatibilityDelayMs\":167}"
        );
    }

