    #[test]
    fn calibration_clear_drops_the_complete_message_binding() {
        let state = NativeDiscordComposerState::default();
        assert!(!state.marker_available());
        let display_bounds = AccessibilityBounds {
            left: 5,
            top: 15,
            right: 360,
            bottom: 90,
        };
        *state.binding.lock().unwrap() = Some(ComposerBinding {
            generation: 7,
            scope_binding_hash: "scope".to_owned(),
            conversation_binding_hash: "conversation".to_owned(),
            composer_name_hash: "composer".to_owned(),
            automation_id_hash: "automation".to_owned(),
            class_name_hash: "class".to_owned(),
            runtime_id: vec![1, 2, 3],
            bounds: bounds(),
            display_bounds,
        });
        assert!(state.marker_available());
        assert_eq!(state.verified_composer_bounds(), Some(display_bounds));
        let presentation_bounds = AccessibilityBounds {
            left: 8,
            top: 18,
            right: 350,
            bottom: 82,
        };
        state
            .apply_adaptive_presentation_bounds(display_bounds, presentation_bounds)
            .expect("bounded presentation crop");
        assert_eq!(
            state.verified_surface_bounds(),
            Some((display_bounds, bounds()))
        );
        assert_eq!(state.verified_composer_bounds(), Some(presentation_bounds));
        state.clear();
        assert!(!state.marker_available());
        assert!(state.binding.lock().unwrap().is_none());
        assert!(state.presentation_bounds.lock().unwrap().is_none());
    }

