    #[test]
    fn native_producer_refuses_replay_reorder_cross_row_window_and_poster_substitution() {
        const OWN_CARRIER: &str = "the quiet harbour keeps every lantern burning tonight";
        const PEER_CARRIER: &str = "the winter garden waits beside the silver morning";
        let (own, peer) = own_and_peer_provider_evidence();
        let stale_root = finish_native_visible_rows(
            provider_rehydrate_read(own.clone(), peer.clone()),
            "trusted-scope",
            7,
            false,
            NativeVisibleRowDiscoveryProfile::reviewed_signed_profile(),
        );
        assert!(stale_root.iter().all(|row| row.attribution.is_none()));
        assert!(!native_row_producer_batch_is_valid(
            &[
                provider_visible_row(peer, PEER_CARRIER),
                provider_visible_row(own, OWN_CARRIER),
            ],
            "trusted-scope",
            7,
        ));

        let (own, mut peer) = own_and_peer_provider_evidence();
        peer.discord_message_id = own.discord_message_id.clone();
        assert!(!native_row_producer_batch_is_valid(
            &[
                provider_visible_row(own, OWN_CARRIER),
                provider_visible_row(peer, PEER_CARRIER),
            ],
            "trusted-scope",
            7,
        ));

        let (own, mut peer) = own_and_peer_provider_evidence();
        peer.native_locator_sha256 = own.native_locator_sha256.clone();
        let mut peer_row = provider_visible_row(peer, PEER_CARRIER);
        peer_row.locator_sha256 = own.native_locator_sha256.clone();
        assert!(!native_row_producer_batch_is_valid(
            &[provider_visible_row(own, OWN_CARRIER), peer_row],
            "trusted-scope",
            7,
        ));

        let (own, mut peer) = own_and_peer_provider_evidence();
        peer.poster_identity_sha256 = own.poster_identity_sha256.clone();
        assert!(!native_row_producer_batch_is_valid(
            &[
                provider_visible_row(own, OWN_CARRIER),
                provider_visible_row(peer, PEER_CARRIER),
            ],
            "trusted-scope",
            7,
        ));

        let (own, peer) = own_and_peer_provider_evidence();
        let rows = [
            provider_visible_row(own, OWN_CARRIER),
            provider_visible_row(peer, PEER_CARRIER),
        ];
        assert!(!native_row_producer_batch_is_valid(&rows, "other-scope", 7));
        assert!(!native_row_producer_batch_is_valid(
            &rows,
            "trusted-scope",
            8
        ));

        let (own, mut peer) = own_and_peer_provider_evidence();
        peer.carrier_sha256 = own.carrier_sha256.clone();
        assert!(!native_row_producer_batch_is_valid(
            &[
                provider_visible_row(own, OWN_CARRIER),
                provider_visible_row(peer, PEER_CARRIER),
            ],
            "trusted-scope",
            7,
        ));
    }

    #[test]
    fn native_provider_identifiers_accept_only_exact_discord_authorities_and_shapes() {
        assert_eq!(
            discord_message_id_from_native_automation_id("message-content-333333333333333333"),
            Some("333333333333333333")
        );
        assert_eq!(
            discord_identity_from_native_avatar_value(
                "https://cdn.discordapp.com/avatars/111111111111111111/avatar.webp"
            ),
            Some("111111111111111111")
        );
        for rejected in [
            "message-content-",
            "message-content-123",
            "prefix-message-content-333333333333333333",
            "message-content-333333333333333333-extra",
        ] {
            assert!(discord_message_id_from_native_automation_id(rejected).is_none());
        }
        for rejected in [
            "https://evil.example/avatars/111111111111111111/avatar.webp",
            "http://cdn.discordapp.com/avatars/111111111111111111/avatar.webp",
            "https://cdn.discordapp.com/avatars/123/avatar.webp",
            "https://cdn.discordapp.com/avatars/111111111111111111",
            "111111111111111111",
        ] {
            assert!(discord_identity_from_native_avatar_value(rejected).is_none());
        }
        let row = AccessibilityBounds {
            left: 100,
            top: 200,
            right: 800,
            bottom: 280,
        };
        let content = AccessibilityBounds {
            left: 172,
            top: 208,
            right: 760,
            bottom: 260,
        };
        assert!(native_poster_avatar_geometry_is_valid(
            row,
            content,
            AccessibilityBounds {
                left: 116,
                top: 208,
                right: 156,
                bottom: 248,
            },
        ));
        // A message-authored image sits in/after the content column, not in the
        // poster slot, even if its resource URL contains `/avatars/<id>/`.
        assert!(!native_poster_avatar_geometry_is_valid(
            row,
            content,
            AccessibilityBounds {
                left: 200,
                top: 220,
                right: 264,
                bottom: 264,
            },
        ));
    }

    /// One simulated transcript child, so the walk's filtering and every bound in
    /// it can be exercised without a single cross-process call.
    struct FakeRow {
        role: u32,
        visible: bool,
        names: Vec<&'static str>,
        nodes: usize,
        bounds: Option<[i32; 4]>,
    }

    fn fake_row(role: u32, text: &'static str) -> FakeRow {
        FakeRow {
            role,
            visible: true,
            names: vec![text],
            nodes: 1,
            bounds: Some([0, 0, 200, 20]),
        }
    }

    fn fake_readers<'a>(
        reads: &'a std::cell::RefCell<Vec<u32>>,
    ) -> (
        impl Fn(&FakeRow) -> Option<u32> + 'a,
        impl Fn(&FakeRow) -> bool + 'a,
        impl Fn(&FakeRow) -> RehydrateRowText + 'a,
        impl Fn(&FakeRow) -> Option<[i32; 4]> + 'a,
        impl Fn(&FakeRow, usize, &[String]) -> Option<NativeDiscordRowAttributionEvidence> + 'a,
    ) {
        (
            move |row: &FakeRow| {
                reads.borrow_mut().push(row.role);
                (row.role != 0).then_some(row.role)
            },
            |row: &FakeRow| row.visible,
            |row: &FakeRow| {
                // The same two things the real walk builds from one pass: the
                // concatenation, for display, and each name on its own, for
                // decoding.
                let mut line = String::new();
                let mut candidates = Vec::new();
                for name in &row.names {
                    rehydrate_push_row_name(&mut line, name, REHYDRATE_MAX_ROW_TEXT_BYTES);
                    rehydrate_push_candidate(&mut candidates, name);
                }
                let line = rehydrate_row_line(&line);
                if let Some(line) = line.as_deref() {
                    rehydrate_push_candidate(&mut candidates, line);
                }
                RehydrateRowText {
                    line,
                    candidates,
                    nodes: row.nodes,
                }
            },
            |row: &FakeRow| row.bounds,
            |_: &FakeRow, _: usize, _: &[String]| None,
        )
    }

    fn walk(
        children: Vec<FakeRow>,
        max_rows: usize,
        max_nodes: usize,
        deadline_after: usize,
    ) -> (RehydrateRead, Vec<u32>) {
        let reads = std::cell::RefCell::new(Vec::new());
        let (role_of, visible, line_of, bounds_of, attribution_of) = fake_readers(&reads);
        let mut checks = 0usize;
        let read = rehydrate_collect_rows(
            children,
            "scope-binding",
            max_rows,
            max_nodes,
            &mut || {
                checks += 1;
                checks > deadline_after
            },
            &RehydrateRowReaders {
                role_of: &role_of,
                visible: &visible,
                line_of: &line_of,
                bounds_of: &bounds_of,
                attribution_of: &attribution_of,
            },
        );
        let observed = reads.borrow().clone();
        (read, observed)
    }

    #[test]
    fn rehydrate_walk_filters_separators_and_keeps_every_readable_row() {
        let (read, _) = walk(
            vec![
                fake_row(MSAA_ROLE_SYSTEM_SEPARATOR, "July 4, 2026"),
                fake_row(
                    MSAA_ROLE_SYSTEM_LISTITEM,
                    "ok i will weekend again with you",
                ),
                fake_row(MSAA_ROLE_SYSTEM_LIST, "Messages in general"),
                fake_row(MSAA_ROLE_SYSTEM_SEPARATOR, "July 5, 2026"),
                fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "ordinary unprotected chat"),
                fake_row(0, "unreadable"),
            ],
            MAX_VISIBLE_CARRIER_ROWS,
            REHYDRATE_MAX_NODES,
            usize::MAX,
        );
        assert_eq!(read.outcome, RehydrateReadOutcome::Complete);
        assert_eq!(read.separators, 2);
        assert_eq!(read.unreadable, 1);
        // The date separators and the nested list are gone; both message rows are
        // present, including the ordinary unprotected one.
        assert_eq!(
            read.rows
                .iter()
                .map(|row| row.line.as_str())
                .collect::<Vec<_>>(),
            vec![
                "ok i will weekend again with you",
                "ordinary unprotected chat"
            ]
        );
        // Row locators are content-free, scoped, and distinguish the two rows.
        assert!(read.rows.iter().all(|row| row.locator_sha256.len() == 64));
        assert_ne!(read.rows[0].locator_sha256, read.rows[1].locator_sha256);
    }

    /// THE defect of 2026-07-26: a row's descendants were concatenated and the
    /// concatenation was handed to the decoder.
    ///
    /// Discord spells one message across several nodes and repeats it inside
    /// every ancestor that contains it -- the live measurement was
    /// `d=1 DOCUMENT(69) / d=2 GROUPING(42) / d=4 PUSHBUTTON(4) /
    /// d=3 STATICTEXT(22)`, four nodes with overlapping text. `decode_token`
    /// arithmetic-decodes the WHOLE word sequence and then demands the parsed
    /// words equal the canonical encoder output exactly, so a single extra or
    /// duplicated word destroys the payload. Nine visible rows produced nine
    /// `pointer_absent` and zero `blob_gone` because of exactly this.
    #[test]
    fn each_descendant_name_is_its_own_candidate_cover_and_the_line_stays_the_display_text() {
        const COVER: &str = "ok i will weekend again with you";
        let (read, _) = walk(
            vec![FakeRow {
                role: MSAA_ROLE_SYSTEM_LISTITEM,
                visible: true,
                // Author, timestamp, a badge, the body, and the body a second
                // time from the ancestor that contains it.
                names: vec!["Deckard", "Today at 3:15 PM", "1", COVER, COVER],
                nodes: 5,
                bounds: Some([0, 0, 700, 44]),
            }],
            MAX_VISIBLE_CARRIER_ROWS,
            REHYDRATE_MAX_NODES,
            usize::MAX,
        );
        assert_eq!(read.rows.len(), 1);
        let row = &read.rows[0];

        // The DISPLAY line is unchanged: it is what is on screen, so it stays the
        // row's honest flagtext, duplication and all.
        assert_eq!(
            row.line,
            format!("Deckard Today at 3:15 PM 1 {COVER} {COVER}")
        );
        // ...and it is exactly what a decoder cannot use, which is why it is not
        // the first thing offered to one.
        assert_ne!(row.line, COVER);

        // The body node, ON ITS OWN, is the first candidate. Nothing here picked
        // it by role or by depth -- every printable name long enough to be a
        // cover is offered, and the HMAC decides. A role/depth heuristic is what
        // broke this feature three separate times on 2026-07-26.
        assert_eq!(row.candidates.first().map(String::as_str), Some(COVER));

        // Author, timestamp and badge are below the length floor, so they are
        // never asked; the duplicated body is deduped away; the whole
        // concatenated line is kept LAST as the fallback for a body Discord
        // splits across sibling nodes.
        assert_eq!(
            row.candidates,
            vec![COVER.to_owned(), row.line.clone()],
            "candidates: body first, deduped, whole line last"
        );
    }

    #[test]
    fn a_candidate_cover_is_normalised_length_floored_and_deduped() {
        const COVER: &str = "ok i will weekend again with you";
        let mut candidates = Vec::new();

        // Too short to carry 96 payload bits under any codec: never asked.
        for short in ["Deckard", "Today at 3:15 PM", "1", "", "   "] {
            rehydrate_push_candidate(&mut candidates, short);
        }
        assert!(candidates.is_empty());

        // Line-shaped covers reach MSAA with real newlines. They are folded to
        // single spaces by the same helper the display line uses, and
        // `parse_words` splits on whitespace either way, so every word boundary
        // survives and no control character can reach the renderer's contract.
        rehydrate_push_candidate(&mut candidates, "ok i will\nweekend again\twith you");
        assert_eq!(candidates, vec![COVER.to_owned()]);

        // The same text arriving again from an ancestor costs nothing: asking an
        // identical string twice can only produce the identical answer twice.
        rehydrate_push_candidate(&mut candidates, COVER);
        rehydrate_push_candidate(&mut candidates, "  ok i will weekend   again with you  ");
        assert_eq!(candidates.len(), 1);

        // A genuinely different node is a genuinely different question.
        rehydrate_push_candidate(&mut candidates, "the quiet harbour waits for morning");
        assert_eq!(candidates.len(), 2);

        // Never a control character, never longer than the row-text cap, never
        // shorter than a cover can be.
        for candidate in &candidates {
            assert!(!candidate.chars().any(char::is_control));
            assert!(candidate.len() >= REHYDRATE_MIN_CANDIDATE_BYTES);
            assert!(candidate.len() <= REHYDRATE_MAX_ROW_TEXT_BYTES);
        }
    }

    #[test]
    fn the_candidate_length_floor_is_derived_from_the_payload_and_never_rejects_a_cover() {
        // 96 payload bits (8 id bytes + a 12-byte truncated HMAC tag) over a
        // 128-word vocabulary is at most 7 bits per word, so no cover is shorter
        // than 14 words -- 14 one-character words and 13 separators = 27 bytes.
        assert_eq!(REHYDRATE_MIN_CANDIDATE_BYTES, 27);
        assert_eq!(REHYDRATE_MIN_CANDIDATE_BYTES, 14 + 13);
        // Well under the row-text cap, so the floor and the ceiling can never
        // cross and silently reject every candidate.
        assert!(REHYDRATE_MIN_CANDIDATE_BYTES < REHYDRATE_MAX_ROW_TEXT_BYTES);
        // A real wordbank cover clears it comfortably; this is a cost filter, not
        // a correctness one, and the HMAC decides everything it lets through.
        let mut candidates = Vec::new();
        rehydrate_push_candidate(&mut candidates, "ok i will weekend again with you");
        assert_eq!(candidates.len(), 1);
    }

    #[test]
    fn a_row_the_reader_cannot_walk_offers_no_candidates_rather_than_a_guess() {
        // Fail closed: an unreadable row is unreadable, never an empty cover the
        // decoder would be asked about and never a row painted at a guess.
        let (read, _) = walk(
            vec![FakeRow {
                role: MSAA_ROLE_SYSTEM_LISTITEM,
                visible: true,
                names: vec!["Deckard", "Today at 3:15 PM"],
                nodes: 2,
                bounds: Some([0, 0, 700, 44]),
            }],
            MAX_VISIBLE_CARRIER_ROWS,
            REHYDRATE_MAX_NODES,
            usize::MAX,
        );
        // The row is still kept -- it is on screen and Discord is showing it --
        // and it simply has nothing worth asking the decoder about.
        assert_eq!(read.rows.len(), 1);
        assert_eq!(read.rows[0].line, "Deckard Today at 3:15 PM");
        assert!(read.rows[0].candidates.is_empty());
    }

    #[test]
    fn rehydrate_walk_stops_at_the_row_cap_without_reading_further_children() {
        let (read, observed) = walk(
            vec![
                fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "one"),
                fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "two"),
                fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "three"),
            ],
            2,
            REHYDRATE_MAX_NODES,
            usize::MAX,
        );
        assert_eq!(read.outcome, RehydrateReadOutcome::RowCapReached);
        assert_eq!(read.rows.len(), 2);
        // The third child's role was never even asked for.
        assert_eq!(observed.len(), 2);
    }

    #[test]
    fn rehydrate_bounds_are_enforced_between_nodes_not_merely_before_the_walk() {
        let rows = || {
            (0..8)
                .map(|_| fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "row"))
                .collect::<Vec<_>>()
        };

        // Wall clock: the deadline trips after the very first check, so exactly one
        // child is read and the walk stops where it stands.
        let (read, observed) = walk(rows(), MAX_VISIBLE_CARRIER_ROWS, REHYDRATE_MAX_NODES, 1);
        assert_eq!(read.outcome, RehydrateReadOutcome::DeadlineExceeded);
        assert_eq!(observed.len(), 1);
        assert!(read.rows.len() <= 1);

        // Node ceiling: three children fit inside a ceiling of five (two nodes each
        // before the text read), the fourth does not, and the walk refuses rather
        // than overrunning.
        let (read, observed) = walk(rows(), MAX_VISIBLE_CARRIER_ROWS, 5, usize::MAX);
        assert_eq!(read.outcome, RehydrateReadOutcome::NodeBudgetExceeded);
        assert!(observed.len() < 8);
        assert_eq!(
            rehydrate_read_stage(read.outcome),
            Some(REHYDRATE_ROW_READ_FAILED)
        );

        // A row whose own descendant walk is expensive is charged for it, so the
        // ceiling really is global rather than per row.
        let mut expensive = fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "row");
        expensive.nodes = REHYDRATE_MAX_NODES;
        let (read, _) = walk(
            vec![expensive],
            MAX_VISIBLE_CARRIER_ROWS,
            REHYDRATE_MAX_NODES,
            usize::MAX,
        );
        assert_eq!(read.outcome, RehydrateReadOutcome::NodeBudgetExceeded);
        assert!(read.rows.is_empty());

        assert_eq!(
            rehydrate_read_stage(RehydrateReadOutcome::DeadlineExceeded),
            Some(REHYDRATE_DEADLINE_EXCEEDED)
        );
        assert_eq!(rehydrate_read_stage(RehydrateReadOutcome::Complete), None);
    }

    #[test]
    fn rehydrate_skips_rows_that_are_not_on_screen_and_rows_with_nothing_printable() {
        let mut offscreen = fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "scrolled away");
        offscreen.visible = false;
        let blank = FakeRow {
            role: MSAA_ROLE_SYSTEM_LISTITEM,
            visible: true,
            names: vec!["\u{0}\u{7f}\n\t"],
            nodes: 1,
            bounds: Some([0, 0, 10, 10]),
        };
        let (read, _) = walk(
            vec![
                offscreen,
                blank,
                fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "still here"),
            ],
            MAX_VISIBLE_CARRIER_ROWS,
            REHYDRATE_MAX_NODES,
            usize::MAX,
        );
        assert_eq!(read.rows.len(), 1);
        assert_eq!(read.rows[0].line, "still here");
        // A row that could not be reduced to anything printable is counted, never
        // silently treated as an empty message.
        assert_eq!(read.unreadable, 1);
    }

    #[test]
    fn rehydrate_walk_keeps_each_kept_rows_on_screen_rectangle() {
        let mut first = fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "alpha");
        first.bounds = Some([10, 20, 300, 44]);
        let mut second = fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "beta");
        second.bounds = Some([10, 48, 300, 72]);
        let (read, _) = walk(
            vec![first, second],
            MAX_VISIBLE_CARRIER_ROWS,
            REHYDRATE_MAX_NODES,
            usize::MAX,
        );
        assert_eq!(
            read.rows.iter().map(|row| row.bounds).collect::<Vec<_>>(),
            vec![Some([10, 20, 300, 44]), Some([10, 48, 300, 72])]
        );
    }

    #[test]
    fn rehydrate_walk_keeps_a_row_whose_rectangle_could_not_be_read() {
        let mut row = fake_row(MSAA_ROLE_SYSTEM_LISTITEM, "no geometry");
        row.bounds = None;
        let (read, _) = walk(
            vec![row],
            MAX_VISIBLE_CARRIER_ROWS,
            REHYDRATE_MAX_NODES,
            usize::MAX,
        );
        // A row is kept by its text; a rectangle that could not be read is not a
        // reason to drop it -- see `RehydrateRowReaders::bounds_of`.
        assert_eq!(read.rows.len(), 1);
        assert_eq!(read.rows[0].bounds, None);
    }

    #[test]
    fn rehydrated_row_rects_reflects_the_last_completed_walk_for_this_scope_and_generation() {
        assert!(rehydrated_row_rects("rects-scope-a", 3).is_empty());
        record_rehydrated_row_rects("rects-scope-a", 3, vec![[10, 20, 300, 44]]);
        assert_eq!(
            rehydrated_row_rects("rects-scope-a", 3),
            vec![[10, 20, 300, 44]]
        );
        // A stale window generation -- the window was replaced -- must never see
        // the previous generation's rectangle.
        assert!(rehydrated_row_rects("rects-scope-a", 4).is_empty());
        // A different conversation must never see another conversation's
        // rectangle either, even under the same generation.
        assert!(rehydrated_row_rects("rects-scope-b", 3).is_empty());
        // Recording again for the same scope and generation replaces, not
        // accumulates.
        record_rehydrated_row_rects("rects-scope-a", 3, vec![[1, 2, 3, 4]]);
        assert_eq!(rehydrated_row_rects("rects-scope-a", 3), vec![[1, 2, 3, 4]]);
    }

    #[test]
    fn rehydrate_row_text_is_one_printable_line_within_the_renderer_bound() {
        let mut line = String::new();
        rehydrate_push_row_name(&mut line, "hello\nthere", REHYDRATE_MAX_ROW_TEXT_BYTES);
        rehydrate_push_row_name(&mut line, "  friend\u{7f}  ", REHYDRATE_MAX_ROW_TEXT_BYTES);
        let finished = rehydrate_row_line(&line).expect("printable");
        assert_eq!(finished, "hello there friend");
        assert!(!finished.chars().any(char::is_control));

        let mut long = String::new();
        rehydrate_push_row_name(&mut long, &"é".repeat(4_000), REHYDRATE_MAX_ROW_TEXT_BYTES);
        let finished = rehydrate_row_line(&long).expect("printable");
        assert!(finished.len() <= REHYDRATE_MAX_ROW_TEXT_BYTES);
        // Truncation never splits a character.
        assert!(finished.chars().all(|character| character == 'é'));

        assert_eq!(rehydrate_row_line("   \u{1f}  "), None);
    }

    #[test]
    fn rehydration_runs_on_a_scope_change_and_refuses_an_immediate_repeat() {
        let state = NativeDiscordComposerState::default();
        assert!(state.begin_rehydrate("scope-a").admitted);
        // EXPECTED VALUE CHANGED, deliberately: this used to be "never again for
        // this binding". The eye has to survive a scroll and a new message in the
        // SAME conversation, so a repeat is now refused by a time floor rather
        // than forever. Back to back, with no clock advanced, the observable
        // behaviour is identical -- a renderer that asked on a tick still reads
        // the transcript zero more times.
        assert!(!state.begin_rehydrate("scope-a").admitted);
        assert!(!state.begin_rehydrate("scope-a").admitted);
        assert!(state.begin_rehydrate("scope-b").admitted);
        assert!(!state.begin_rehydrate("scope-b").admitted);
        assert!(state.begin_rehydrate("scope-a").admitted);
        // A detach ends the session, so the next open is a change again rather
        // than an empty transcript behind an opaque shield.
        state.clear();
        assert!(state.begin_rehydrate("scope-a").admitted);
    }

    #[test]
    fn same_scope_rehydration_is_admitted_again_once_the_floor_has_passed() {
        let state = NativeDiscordComposerState::default();
        let start = Instant::now();
        let floor = Duration::from_millis(REHYDRATE_MIN_INTERVAL_MS);
        assert!(state.begin_rehydrate_at("scope-a", start).admitted);
        // One millisecond short of the floor is still refused...
        let early = state.begin_rehydrate_at("scope-a", start + floor - Duration::from_millis(1));
        assert!(!early.admitted);
        assert_eq!(early.retry_after_ms, 1);
        // ...and a refusal never moves the floor forward, so the operator's next
        // edge is not pushed further away by the one that was just refused.
        let still_early = state.begin_rehydrate_at("scope-a", start + Duration::from_millis(250));
        assert!(!still_early.admitted);
        assert_eq!(still_early.retry_after_ms, REHYDRATE_MIN_INTERVAL_MS - 250);
        // Exactly at the floor the scroll or new-message edge gets its read.
        let due = state.begin_rehydrate_at("scope-a", start + floor);
        assert!(due.admitted);
        assert_eq!(due.retry_after_ms, 0);
        // And the floor restarts from the admitted read, not from the refusals.
        assert!(
            !state
                .begin_rehydrate_at("scope-a", start + floor + Duration::from_millis(1))
                .admitted
        );
    }

    #[test]
    fn a_scope_change_is_never_floored() {
        let state = NativeDiscordComposerState::default();
        let start = Instant::now();
        assert!(state.begin_rehydrate_at("scope-a", start).admitted);
        // Switching conversation must repaint at once: a new conversation showing
        // the previous one's rows for up to three quarters of a second is not a
        // rate limit, it is the wrong conversation on screen.
        let switched = state.begin_rehydrate_at("scope-b", start + Duration::from_millis(1));
        assert!(switched.admitted);
        assert_eq!(switched.retry_after_ms, 0);
        // Switching back is a change too, even though "scope-a" was read 2 ms ago.
        assert!(
            state
                .begin_rehydrate_at("scope-a", start + Duration::from_millis(2))
                .admitted
        );
    }

    #[test]
    fn a_visible_message_row_keeps_the_rectangle_it_was_read_with() {
        // The contract the placement path depends on: a row's own screen
        // rectangle travels with its text instead of being dropped one line after
        // it is read. `None` stays a first-class answer -- a row whose rectangle
        // could not be read is still returned, it simply cannot be painted over.
        let placed = VisibleMessageRow {
            locator_sha256: "locator".to_owned(),
            line: "see you at six".to_owned(),
            decode_candidates: Vec::new(),
            bounds: Some([10, 20, 300, 44]),
            attribution: None,
        };
        let unplaceable = VisibleMessageRow {
            locator_sha256: "locator-2".to_owned(),
            line: "and again tomorrow".to_owned(),
            decode_candidates: Vec::new(),
            bounds: None,
            attribution: None,
        };
        assert_eq!(placed.bounds, Some([10, 20, 300, 44]));
        assert_eq!(unplaceable.bounds, None);
        assert_eq!(placed.line, "see you at six");
    }

    // -----------------------------------------------------------------------
    // Guided deletion: the binding between the pure workflow and the one
    // bounded transcript reader this file already ships.
    // -----------------------------------------------------------------------

    fn read_row(line: &str, top: i32, bottom: i32) -> VisibleMessageRow {
        VisibleMessageRow {
            locator_sha256: stable_hash("test-row", line),
            line: line.to_owned(),
            decode_candidates: Vec::new(),
            bounds: Some([0, top, 700, bottom]),
            attribution: None,
        }
    }

    #[test]
    fn only_rows_that_begin_with_the_operators_own_name_are_deletion_candidates() {
        let names = vec!["Deckard".to_owned(), "Rose".to_owned()];
        assert!(row_is_authored_by_operator(
            "Deckard 10:04 see you at six",
            &names
        ));
        assert!(row_is_authored_by_operator(
            "  Rose: and again tomorrow",
            &names
        ));
        // A longer handle that merely starts the same way is not the operator.
        assert!(!row_is_authored_by_operator(
            "Deckardson 10:04 hello",
            &names
        ));
        assert!(!row_is_authored_by_operator(
            "Someone else entirely",
            &names
        ));
        // An empty or absurd name list can never make a row deletable.
        assert!(!row_is_authored_by_operator("Deckard hello", &[]));
        assert!(!row_is_authored_by_operator(
            "Deckard hello",
            &["".to_owned()]
        ));
        assert!(!row_is_authored_by_operator(
            "Deckard hello",
            &["D".repeat(MAX_OPERATOR_NAME_BYTES + 1)]
        ));
    }

    #[test]
    fn a_scan_keeps_only_the_operators_rows_and_numbers_them_over_the_whole_list() {
        let rows = vec![
            read_row("Deckard first", 0, 44),
            read_row("Rose reply", 44, 88),
            read_row("Deckard second", 88, 132),
        ];
        let scan = deletion_scan_from_rows(
            &rows,
            "scope",
            9,
            &["Deckard".to_owned()],
            MAX_VISIBLE_CARRIER_ROWS,
            Some(true),
        );
        assert_eq!(scan.rows_seen, 3);
        assert_eq!(scan.candidates.len(), 2);
        // Ordinals are taken over EVERY row, not over the kept ones: an ordinal
        // that counted only the operator's rows could never be re-resolved
        // against the live list.
        assert_eq!(
            scan.candidates
                .iter()
                .map(|row| row.scan_ordinal)
                .collect::<Vec<_>>(),
            vec![0, 2]
        );
        // All three rows are 44 px tall, so the shape ordinal is what tells them
        // apart within one shape.
        assert_eq!(
            scan.candidates
                .iter()
                .map(|row| row.shape_ordinal)
                .collect::<Vec<_>>(),
            vec![0, 2]
        );
        assert!(scan.candidates.iter().all(|row| row.authored_by_operator));
        assert_eq!(
            scan.scope_binding_hash,
            stable_hash("osl-discord-scope", "scope")
        );
        assert_eq!(scan.generation, 9);
        assert_eq!(scan.walk, guided_deletion::WalkCompleteness::Complete);
    }

    #[test]
    fn a_row_without_a_readable_rectangle_is_unreadable_never_a_candidate() {
        let rows = vec![
            VisibleMessageRow {
                locator_sha256: "a".to_owned(),
                line: "Deckard invisible".to_owned(),
                decode_candidates: Vec::new(),
                bounds: None,
                attribution: None,
            },
            read_row("Deckard visible", 0, 44),
        ];
        let scan = deletion_scan_from_rows(
            &rows,
            "scope",
            1,
            &["Deckard".to_owned()],
            MAX_VISIBLE_CARRIER_ROWS,
            Some(true),
        );
        assert_eq!(scan.rows_unreadable, 1);
        assert_eq!(scan.candidates.len(), 1);
        assert_eq!(scan.candidates[0].scan_ordinal, 0);
    }

    #[test]
    fn without_the_walks_own_verdict_a_read_at_its_cap_can_never_prove_absence() {
        // The conservative fallback, for a scope or generation the reader has not
        // reported on.
        for rows in [0usize, 32, 33] {
            assert_eq!(
                deletion_walk_completeness(rows, 32, None),
                guided_deletion::WalkCompleteness::Truncated
            );
        }
        assert_eq!(
            deletion_walk_completeness(31, 32, None),
            guided_deletion::WalkCompleteness::Complete
        );
    }

    #[test]
    fn the_walks_own_verdict_outranks_the_row_count_in_both_directions() {
        // A full transcript is about 32 rows and the cap is 32, so without this
        // the feature refused to verify anything in exactly the conversations it
        // is for. The walk knew; the reader simply was not keeping the answer.
        assert_eq!(
            deletion_walk_completeness(32, 32, Some(true)),
            guided_deletion::WalkCompleteness::Complete
        );
        // And a short read that stopped on its node ceiling is truncated however
        // few rows came back -- which the row count could never have caught.
        assert_eq!(
            deletion_walk_completeness(3, 32, Some(false)),
            guided_deletion::WalkCompleteness::Truncated
        );
        // An empty read is never complete, whatever is reported: nothing saw a
        // transcript at all.
        assert_eq!(
            deletion_walk_completeness(0, 32, Some(true)),
            guided_deletion::WalkCompleteness::Truncated
        );
    }

    #[test]
    fn the_read_verdict_is_scoped_to_one_conversation_and_one_generation() {
        assert_eq!(
            last_transcript_read_was_complete("verdict-scope-a", 4),
            None
        );
        record_transcript_read_completeness("verdict-scope-a", 4, true);
        assert_eq!(
            last_transcript_read_was_complete("verdict-scope-a", 4),
            Some(true)
        );
        // A replaced window or another conversation answers nothing, so the
        // caller falls back to the conservative rule instead of reusing a verdict
        // that was never about this read.
        assert_eq!(
            last_transcript_read_was_complete("verdict-scope-a", 5),
            None
        );
        assert_eq!(
            last_transcript_read_was_complete("verdict-scope-b", 4),
            None
        );
        record_transcript_read_completeness("verdict-scope-a", 4, false);
        assert_eq!(
            last_transcript_read_was_complete("verdict-scope-a", 4),
            Some(false)
        );
    }

    #[test]
    fn only_a_walk_that_reached_the_end_of_the_list_counts_as_complete() {
        assert!(rehydrate_read_was_complete(RehydrateReadOutcome::Complete));
        // Rows were kept, which is right for putting the conversation back on
        // screen, but there are more of them.
        assert!(!rehydrate_read_was_complete(
            RehydrateReadOutcome::RowCapReached
        ));
        assert!(!rehydrate_read_was_complete(
            RehydrateReadOutcome::DeadlineExceeded
        ));
        assert!(!rehydrate_read_was_complete(
            RehydrateReadOutcome::NodeBudgetExceeded
        ));
    }

    #[test]
    fn a_planned_row_is_resolved_by_shape_and_length_and_ambiguity_is_refused() {
        let rows = vec![
            read_row("Deckard first", 0, 44),
            read_row("Deckard other", 44, 88),
            read_row("Deckard xxxxx", 88, 156),
        ];
        let planned = |ordinal: usize, height: i32, len: usize| guided_deletion::ScannedRow {
            scan_ordinal: ordinal,
            shape_ordinal: 0,
            shape: guided_deletion::RowShape {
                height_px: height,
                children: 0,
            },
            text_len: len,
            authored_by_operator: true,
        };
        // Unique (height, length): resolved wherever it sits.
        assert_eq!(
            resolve_planned_deletion_row(&rows, &planned(2, 68, 13)),
            (guided_deletion::RowResolution::Resolved, Some(2))
        );
        // Two rows share (44, 13). The planned ordinal disambiguates.
        assert_eq!(
            resolve_planned_deletion_row(&rows, &planned(1, 44, 13)),
            (guided_deletion::RowResolution::Resolved, Some(1))
        );
        // The same pair with an ordinal that is not one of them is ambiguous, not
        // a guess at the nearest one.
        assert_eq!(
            resolve_planned_deletion_row(&rows, &planned(7, 44, 13)),
            (guided_deletion::RowResolution::Ambiguous, None)
        );
        // Nothing matches: the row is gone, and `Gone` is `Held`, never verified.
        assert_eq!(
            resolve_planned_deletion_row(&rows, &planned(0, 44, 99)),
            (guided_deletion::RowResolution::Gone, None)
        );
        assert_eq!(
            resolve_planned_deletion_row(&[], &planned(0, 44, 13)),
            (guided_deletion::RowResolution::Unreadable, None)
        );
    }

    #[test]
    fn the_census_counts_the_target_by_its_own_text_and_by_its_shape() {
        let rows = vec![
            read_row("Deckard see you at six", 0, 44),
            read_row("Rose ok", 44, 88),
            read_row("Deckard see you at six", 88, 132),
            read_row("Rose taller reply", 132, 200),
        ];
        let census = deletion_census_from_rows(
            &rows,
            "Deckard see you at six",
            44,
            MAX_VISIBLE_CARRIER_ROWS,
            guided_deletion::SurfaceIdentity::Reproven,
            Some(true),
        );
        assert_eq!(census.total_rows, 4);
        assert_eq!(census.target_shape_rows, 3);
        assert_eq!(census.target_text_rows, 2);
        assert_eq!(census.walk, guided_deletion::WalkCompleteness::Complete);
        // Deleting one of the two identical rows is provable: the text count drops
        // by exactly one and nothing else disappears.
        let after = deletion_census_from_rows(
            &rows[1..],
            "Deckard see you at six",
            44,
            MAX_VISIBLE_CARRIER_ROWS,
            guided_deletion::SurfaceIdentity::Reproven,
            Some(true),
        );
        assert_eq!(
            guided_deletion::classify_removal(census, after),
            guided_deletion::RemovalVerdict::Proven
        );
    }

    #[test]
    fn the_census_carries_counts_only_and_no_row_text() {
        let rows = vec![read_row("Deckard see you at six", 0, 44)];
        let census = deletion_census_from_rows(
            &rows,
            "Deckard see you at six",
            44,
            MAX_VISIBLE_CARRIER_ROWS,
            guided_deletion::SurfaceIdentity::Reproven,
            Some(true),
        );
        let rendered = format!("{census:?}");
        assert!(!rendered.contains("see you at six"));
        assert!(!rendered.contains("Deckard"));
    }

    #[cfg(feature = "core")]
    #[test]
    fn native_visible_row_qa_receipt_has_nonempty_own_and_peer_positive_controls() {
        let (own, peer) = own_and_peer_provider_evidence();
        let discovery_profile = signed_discord_visible_row_discovery_profile();
        let admitted_rows = finish_native_visible_rows(
            provider_rehydrate_read(own.clone(), peer.clone()),
            "trusted-scope",
            7,
            true,
            discovery_profile,
        );
        assert_eq!(admitted_rows.len(), 2);
        assert!(admitted_rows.iter().all(|row| row.attribution.is_some()));
        let receipt = native_visible_row_qa_receipt_from_rows(
            "a".repeat(40),
            "b".repeat(64),
            "trusted-scope",
            7,
            admitted_rows,
        );
        assert!(receipt.accepted);
        assert_eq!(receipt.rows_observed, 2);
        assert_eq!(receipt.proof_some, 2);
        assert_eq!(receipt.proof_none, 0);
        assert_eq!(receipt.own_rows, 1);
        assert_eq!(receipt.peer_rows, 1);
        assert_eq!(
            receipt.refusal_reason_counts,
            NativeVisibleRowQaRefusalReasonCounts::default()
        );

        let refused_rows = finish_native_visible_rows(
            provider_rehydrate_read(own, peer),
            "trusted-scope",
            7,
            true,
            NativeVisibleRowDiscoveryProfile::incomplete_for_tests(),
        );
        assert_eq!(refused_rows.len(), 2);
        assert!(refused_rows.iter().all(|row| row.attribution.is_none()));
        let refused = native_visible_row_qa_receipt_from_rows(
            "a".repeat(40),
            "b".repeat(64),
            "trusted-scope",
            7,
            refused_rows,
        );
        assert!(!refused.accepted);
        assert_eq!(refused.rows_observed, 2);
        assert_eq!(refused.proof_some, 0);
        assert_eq!(refused.proof_none, 2);
    }

    #[test]
    fn native_visible_row_qa_receipt_refuses_zero_and_proof_none_mutations() {
        let zero = native_visible_row_qa_receipt_from_rows(
            "a".repeat(40),
            "b".repeat(64),
            "trusted-scope",
            7,
            Vec::new(),
        );
        assert!(!zero.accepted);
        assert_eq!(zero.rows_observed, 0);
        assert_eq!(zero.proof_some, 0);
        assert_eq!(zero.refusal_reason_counts.no_rows_observed, 1);

        let missing = native_visible_row_qa_receipt_from_rows(
            "a".repeat(40),
            "b".repeat(64),
            "trusted-scope",
            7,
            vec![VisibleMessageRow {
                locator_sha256: "native-locator-must-not-escape".to_owned(),
                line: "message text must not escape".to_owned(),
                decode_candidates: vec!["carrier must not escape".to_owned()],
                bounds: Some([1, 2, 3, 4]),
                attribution: None,
            }],
        );
        assert!(!missing.accepted);
        assert_eq!(missing.rows_observed, 1);
        assert_eq!(missing.proof_some, 0);
        assert_eq!(missing.proof_none, 1);
        assert_eq!(missing.refusal_reason_counts.no_rows_observed, 0);
        assert_eq!(missing.refusal_reason_counts.native_proof_unavailable, 1);
    }

    #[test]
    fn native_visible_row_qa_receipt_serialization_excludes_content_ids_and_geometry() {
        const CARRIER: &str = "visible carrier must never enter the receipt";
        const MESSAGE_ID: &str = "333333333333333333";
        let evidence = native_row_attribution_from_provider(
            provider_observation(
                MESSAGE_ID,
                "111111111111111111",
                "111111111111111111",
                CARRIER,
                71,
            ),
            &[CARRIER.to_owned()],
            "private-scope-binding",
            19,
            0,
        )
        .expect("positive native evidence");
        let receipt = native_visible_row_qa_receipt_from_rows(
            "c".repeat(40),
            stable_hash(
                "discord-native-visible-row-qa-target-v1",
                "distinctive-raw-hwnd\u{1f}distinctive-raw-process-id",
            ),
            "private-scope-binding",
            19,
            vec![VisibleMessageRow {
                locator_sha256: evidence.native_locator_sha256.clone(),
                line: CARRIER.to_owned(),
                decode_candidates: vec![
                    CARRIER.to_owned(),
                    "https://cdn.discordapp.com/avatars/private-avatar".to_owned(),
                ],
                bounds: Some([101, 202, 303, 404]),
                attribution: Some(evidence),
            }],
        );
        let encoded = serde_json::to_string(&receipt).expect("receipt serializes");
        for forbidden in [
            CARRIER,
            MESSAGE_ID,
            "111111111111111111",
            "private-avatar",
            "private-scope-binding",
            "distinctive-raw-hwnd",
            "distinctive-raw-process-id",
            "locatorSha256",
            "discordMessageId",
            "posterIdentity",
            "decodeCandidates",
            "bounds",
            "line",
        ] {
            assert!(
                !encoded.contains(forbidden),
                "receipt leaked forbidden value/key {forbidden}"
            );
        }
        assert!(encoded.len() < 1_024, "receipt must remain tightly bounded");
    }

    #[test]
    fn native_visible_row_qa_osl_target_hash_binds_window_and_process() {
        let baseline = native_visible_row_qa_osl_target_sha256(101, 202).expect("valid identity");
        assert_eq!(baseline.len(), 64);
        assert_ne!(
            baseline,
            native_visible_row_qa_osl_target_sha256(102, 202).unwrap()
        );
        assert_ne!(
            baseline,
            native_visible_row_qa_osl_target_sha256(101, 203).unwrap()
        );
        assert!(native_visible_row_qa_osl_target_sha256(0, 202).is_none());
        assert!(native_visible_row_qa_osl_target_sha256(101, 0).is_none());
        assert!(!baseline.contains("101"));
        assert!(!baseline.contains("202"));
    }

    #[test]
    fn native_visible_row_qa_source_uses_the_real_adopted_producer_route() {
        let source = include_str!("native_discord_adapter.rs");
        let start = source
            .find("pub fn request_native_visible_row_qa_receipt(")
            .expect("QA producer request must exist");
        let end = source[start..]
            .find("// ---------------------------------------------------------------------------")
            .map(|offset| start + offset)
            .expect("QA request section must remain bounded");
        let route = &source[start..end];
        for required in [
            "with_current_discord_accessibility_target",
            "trusted(target.process_id)",
            "windows::read_visible_message_rows_detached(",
            "target.generation",
            "target.window",
            "target.process_id",
            "native_visible_row_qa_receipt_from_rows(",
        ] {
            assert!(
                route.contains(required),
                "missing production route: {required}"
            );
        }
        for forbidden in [
            "SetForegroundWindow",
            "set_focus",
            "SendInput",
            "reqwest",
            "discord_message_id",
            ".line",
        ] {
            assert!(
                !route.contains(forbidden),
                "QA request must remain non-mutating and content-free: {forbidden}"
            );
        }
    }
